parameters.jsCode:
const items = $input.all();
if (!items || items.length === 0) return []; // Graceful halt: no chats today.

let transcript = "--- START OF DAILY CHAT LOG ---\n";
let ids = [];

items.forEach(item => {
    const msg = item.json.message_text;
    // Ignore empty lines
    if (msg && msg.trim() !== "") {
        transcript += `[${item.json.sender_name}]: ${msg}\n`;
    }
    ids.push(item.json.id);
});

transcript += "--- END OF DAILY CHAT LOG ---";

return { 
    json: { 
        transcript: transcript,
        idsList: ids.join(',') // Creates a string like "1,2,3" for the DB update
    } 
};

parameters.query:
UPDATE whatsapp_daily_logs 
SET processed = TRUE 
WHERE id IN ({{ $('Formatter & Gateway').item.json.idsList }});
